'use server'

import { revalidatePath } from 'next/cache'

export async function toggleNotificationPreference(currentValue: boolean) {
  const newValue = !currentValue

  await new Promise(resolve => setTimeout(resolve, 500))

  console.log(`Notification preference: ${currentValue} -> ${newValue}`)

  revalidatePath('/')

  return { success: true, notificationsEnabled: newValue }
}

'use client'

import { useActionState } from 'react'
import { toggleNotificationPreference } from './actions'

function SubmitButton() {
  const { pending } = useFormStatus()

  return (
    <button 
      type="submit" 
      disabled={pending}
      className="toggle-btn"
    >
      {pending ? 'Updating...' : 'Toggle'}
    </button>
  )
}

export default function Home() {
  const [state, formAction] = useActionState(toggleNotificationPreference, {
    success: false,
    notificationsEnabled: true
  })

  return (
    <main>
      <h1>Settings</h1>
      <form action={formAction}>
        <label className="notification-setting">
          <span>Enable Notifications</span>
          <input 
            type="hidden" 
            name="currentValue" 
            value={state.notificationsEnabled.toString()} 
          />
          <div className="toggle-container">
            <span className={`status ${state.notificationsEnabled ? 'on' : 'off'}`}>
              {state.notificationsEnabled ? 'ON' : 'OFF'}
            </span>
            <SubmitButton />
          </div>
        </label>
      </form>

      <style jsx>{`
        main {
          padding: 2rem;
          max-width: 600px;
          margin: 0 auto;
        }
        .notification-setting {
          display: flex;
          flex-direction: column;
          gap: 1rem;
        }
        .toggle-container {
          display: flex;
          align-items: center;
          gap: 1rem;
        }
        .status {
          font-weight: bold;
          padding: 0.5rem 1rem;
          border-radius: 4px;
        }
        .status.on {
          background: #d4edda;
          color: #155724;
        }
        .status.off {
          background: #f8d7da;
          color: #721c24;
        }
        .toggle-btn {
          padding: 0.5rem 1rem;
          background: #0070f3;
          color: white;
          border: none;
          border-radius: 4px;
          cursor: pointer;
        }
        .toggle-btn:disabled {
          background: #ccc;
          cursor: not-allowed;
        }
      `}</style>
    </main>
  )
}

