'use server'

import { revalidatePath } from 'next/cache'

export async function toggleNotificationPreference(
  _prevState: { success: boolean; notificationsEnabled: boolean },
  formData: FormData
) {
  const currentValue = formData.get('currentValue') === 'true'
  const newValue = !currentValue

  await new Promise(resolve => setTimeout(resolve, 500))

  console.log(`Notification preference: ${currentValue} -> ${newValue}`)

  revalidatePath('/')

  return { success: true, notificationsEnabled: newValue }
}

